import{_ as t}from"./chunks/synth_mechadrum.rVUZe1uD.js";import{_ as a,o as s,c as i,a2 as r}from"./chunks/framework.hw3Av5Vn.js";const g=JSON.parse('{"title":"MechaDrum","description":"","frontmatter":{},"headers":[],"relativePath":"synths/engines/MECHADRUM.md","filePath":"synths/engines/MECHADRUM.md"}'),o={name:"synths/engines/MECHADRUM.md"};function n(h,e,l,d,c,p){return s(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="mechadrum" tabindex="-1">MechaDrum <a class="header-anchor" href="#mechadrum" aria-label="Permalink to &quot;MechaDrum&quot;">​</a></h1><p>MechaDrum is a drum machine of ten drums, chosen by its Machine: Kick, Hard Kick, Synth Kick, Snare, Clap, Rim, Hats, Cowbell, Acoustic Tom and Karplus Drum. Each is shaped by the same five knobs, Pitch, Decay, Color, Shape and Sweep, which each drum reads in its own way. The note tunes the drum in half steps from middle C, and a harder hit is brighter. A drum cuts its own last hit unless Overlap is on, and drums of one Choke group cut each other, as a closed hat cuts an open one. Only a percussion instrument offers it.</p><p><img src="'+t+'" alt="The Oscillators tab of MechaDrum"></p><h2 id="how-mechadrum-is-built" tabindex="-1">How MechaDrum Is Built <a class="header-anchor" href="#how-mechadrum-is-built" aria-label="Permalink to &quot;How MechaDrum Is Built&quot;">​</a></h2><p>A hit isn&#39;t played sample by sample as a note is: when its note arrives, the whole hit is rendered at once, on the thread that reads the notes, never in the audio callback, and kept, so that the next hit of the same drum at the same settings is replayed. Its noise comes from a random source seeded by what the hit is, so that a replay and a WAV export match to the sample. Every hit ends alike: a high-pass filter takes out any offset, a fade ends it where it falls silent, and a gain sets its loudest moment to the same peak.</p><p>The recipes follow the circuits of the drum machines that defined electronic drums:</p><ul><li><strong>Kick</strong>: a sine whose pitch starts high and sweeps down, by Sweep, decaying by Decay; Color adds a click, a short burst of filtered noise and a couple of harmonics, and Shape drives it into a soft clipper for punch. With Color, Shape and Sweep at 0 and a long Decay it is the pure sine kick, a clean low tone with nothing added, whose weight is all in its body; a little Sweep gives it a thump at the start.</li><li><strong>Hard Kick</strong>: a sine held at full for a moment, by Shape, before it decays, with a steep pitch sweep, a click and a burst of noise, clipped hard.</li><li><strong>Synth Kick</strong>: a wave that morphs, by Color, from a sine through a triangle towards a square, by adding odd harmonics, its pitch swept down over several octaves while a low-pass filter falls with it, its coefficients moved every few samples and its state kept.</li><li><strong>Snare</strong>: two triangle tones a little apart, bumped up in pitch at the start, under a rattle of high-passed noise with a snap at its start; Shape balances the tones against the rattle, and Color brightens the rattle.</li><li><strong>Clap</strong>: several short bursts of noise a few milliseconds apart, each slightly late at random, as hands never clap together, then a tail, all through a band-pass filter; Color sets how many bursts there are and how close.</li><li><strong>Rim</strong>: two sines in a clashing ratio, the high one fading faster, with a click, driven by Shape.</li><li><strong>Hats</strong>: six square waves at clashing, unrelated pitches, added and mixed with noise by Color, through band-pass and high-pass filters. The squares are left naive, a little aliased, as the digital edge of the original circuit has it.</li><li><strong>Cowbell</strong>: two squares through a band-pass, as the original&#39;s two-tone circuit.</li><li><strong>Acoustic Tom</strong>: a physical model of a struck circular drum head. Its modes ring at the ratios the zeros of the Bessel functions give, as a real membrane&#39;s do, those a strike at that place can ring; Shape sets where it is struck, from the centre to the edge, and Color with the velocity how hard the mallet is, a hard mallet&#39;s short contact ringing the high modes. Each mode fades faster the higher it is, the head&#39;s tension glides down after a hard hit as a real head&#39;s does, and the shell adds its noise.</li><li><strong>Karplus Drum</strong>: the Karplus and Strong waveguide drum. A burst of noise circulates in a delay line one period of the note long; on each pass, each sample is averaged with its neighbour, which dulls and fades it as a string&#39;s sound fades, and its sign is flipped at random, by Shape, which turns a plucked string into a drum. Color brightens the burst and the averaging, and Sweep drops the pitch at the start by squeezing the line.</li></ul>',7)])])}const f=a(o,[["render",n]]);export{g as __pageData,f as default};
